export const TUTORIAL_STEPS=[
 {title:'대표님의 첫 5년',text:'안녕하세요, 안내 비서 모아예요. 대표님은 한 달에 4주를 배분하고, 그 결과로 달라진 회사와 삶을 운영해요. 60개월 뒤의 결말은 매출뿐 아니라 건강, 빚, 관계와 선택에 따라 달라져요.',tip:'처음에는 이번 달 일정부터 시작하면 돼요.',target:'.planner'},
 {title:'한 달의 4주 채우기',text:'할 일 고르기에서 고객 조사, 제품 만들기, 영업, 공부, 휴식 중 하나를 누르면 1주가 추가돼요. 같은 일을 여러 번 골라도 돼요. 일정의 ×를 누르면 그 주를 비울 수 있어요.',tip:'추천 일정으로 네 주를 채워볼까요? 아직 시간이 흐르지는 않아요.',target:'#action-list',practice:true},
 {title:'현금과 체력을 확인하기',text:'이번 달의 일정 아래에서 활동비, 월 고정비와 예상 남은 체력을 확인해요. 체력 25 미만이면 성장 효과가 줄어드니 휴식을 넣어 주세요. 현금이 비용보다 부족하면 일정을 바꾸거나 자금 대책을 확인해요.',tip:'보유 기술 67 이상인 대표는 매달 제품 만들기 1주가 필요해요.',target:'.plan-summary'},
 {title:'이번 달 시작하기',text:'4주를 모두 채웠다면 이번 달 시작하기를 눌러요. 지원사업이나 행사는 할 일 고르기의 이번 달 선택에서 참가 여부를 정해요. 월말에는 매출·비용·손익과 능력치 변화를 확인할 수 있어요.',tip:'매출에서 원가·활동비·고정비를 뺀 금액이 월 손익이에요.',target:'.planner'},
 {title:'사건과 조언 고르기',text:'사건이 생기면 선택지를 고르고 주변 사람의 조언을 살펴봐요. 찬성·조건부·반대 중 하나를 골라 같은 의견을 낸 인물들의 호감도를 높이고 결과를 확인하면 직접 다음 달의 일정을 준비할 수 있어요.',tip:'선택에 따라 호감도와 후속 사건이 달라져요. AUTO는 이 과정을 대신 진행해요.',target:'.assistant-briefing'},
 {title:'목표와 배움을 챙기기',text:'나의 상태에는 초기 계획서로 만든 목표와 기한이 있어요. 달력에서는 지원사업·전시회·출장 일정을, 성장 기록에서는 지난 선택을 볼 수 있어요. 창업 위키의 용어 짝맞추기로 낯선 말을 익혀보세요.',tip:'부동산의 추가 효과는 그곳에서 한 달을 운영했을 때 적용돼요.',target:'.assistant-briefing'},
 {title:'마지막으로, 직접 저장하기',text:'현재 진행은 브라우저에 자동 저장돼요. 첫 화면의 자동 저장 이어하기로 돌아오세요. 오른쪽 위 저장 버튼을 누르면 현재 시점을 수동 슬롯에도 보관해요.',tip:'다른 게임을 시작하기 전에는 보관할 진행을 슬롯에 저장하세요. 나가기는 자진 폐업이며, 건너뛰기는 남은 기간 자동 진행이에요.',target:'.topactions',save:true}
];
export function tutorialView(step,state,forecast){const t=TUTORIAL_STEPS[step];return `<div class="moa-tutorial"><img src="assets/npc-ai_agent.png" alt="안내 비서 모아"><div><span class="tutorial-count">PLAY GUIDE · ${step+1} / ${TUTORIAL_STEPS.length}</span><h3>${t.title}</h3><p>${t.text}</p><div class="tutorial-tip">${t.tip}</div>${t.practice?`<div class="tutorial-practice"><b>현재 일정 ${state?.plan?.length||0} / 4주</b><button class="primary" data-action="tutorial-practice" ${!state||state.ending||state.pending||state.lastScene?.unread?'disabled':''}>추천 일정으로 직접 채워보기</button>${state?.plan?.length===4&&forecast?`<p>활동비 ${forecast.cost.toLocaleString()}만 원 · 고정비 ${forecast.fixed.toLocaleString()}만 원<br>예상 남은 체력 ${forecast.health} / 100</p>`:''}</div>`:''}${t.save&&state?'<button class="primary" data-action="tutorial-save">지금 시점 저장하기</button>':''}</div></div><div class="tutorial-dots" aria-label="튜토리얼 진행">${TUTORIAL_STEPS.map((_,i)=>`<span class="${i===step?'active':''}"></span>`).join('')}</div><div class="tutorial-navigation"><button class="quiet" data-action="tutorial-prev" ${step===0?'disabled':''}>이전</button><button class="quiet" data-action="tutorial-locate">화면에서 보기</button><button class="primary" data-action="${step===TUTORIAL_STEPS.length-1?'tutorial-done':'tutorial-next'}">${step===TUTORIAL_STEPS.length-1?'플레이 시작':'다음'}</button></div>`;}
